preToolUse.powershell:
$input_data = $input | ConvertFrom-Json -ErrorAction SilentlyContinue
$tool = $input_data.tool
$args = $input_data.args | Out-String
# Block rm -rf on source directories
if ($args -match 'rm.*-rf.*(src|lib|app|components)') {
  '{"decision":"deny","reason":"Blocked destructive rm -rf on source directory"}'
} else {
  '{"decision":"allow"}'
}
